import React, { useState, Suspense, lazy } from "react";
import "./App.css";
import { BrowserRouter, Routes, Route } from "react-router-dom";
import { HelmetProvider } from 'react-helmet-async';
import Header from "./components/Header";
import Hero from "./components/Hero";
import ProjectModal from "./components/ProjectModal";
import Footer from "./components/Footer";
import FloatingContactButton from "./components/FloatingContactButton";
import SEO from "./components/SEO";
import { ThemeProvider } from "./context/ThemeContext";

// Lazy load segments
const ProjectsShowcase = lazy(() => import("./components/ProjectsShowcase"));
const ExperienceTimeline = lazy(() => import("./components/ExperienceTimeline"));
const SkillsGrid = lazy(() => import("./components/SkillsGrid"));
const Certifications = lazy(() => import("./components/Certifications"));

const LoadingFallback = () => (
  <div className="py-20 flex justify-center items-center">
    <div className="w-12 h-12 border-4 border-primary rounded-full animate-spin"></div>
  </div>
);

const Home = () => {
  const [isContactModalOpen, setIsContactModalOpen] = useState(false);

  return (
    <div className="min-h-screen bg-surface text-on-surface font-body selection:bg-primary selection:text-on-primary-container">
      <SEO />
      <Header />
      <Hero onContactClick={() => setIsContactModalOpen(true)} />
      
      <Suspense fallback={<LoadingFallback />}>
          <ExperienceTimeline />
          <SkillsGrid />
          <ProjectsShowcase />
          <Certifications />
      </Suspense>

      <Footer />
      <FloatingContactButton onClick={() => setIsContactModalOpen(true)} />
      {/* Reused ContactModal if we still have it */}
    </div>
  );
};

function App() {
  const basename = process.env.PUBLIC_URL || '';
  
  return (
    <HelmetProvider>
      <ThemeProvider>
        <div className="App transition-colors duration-300">
          <BrowserRouter basename={basename}>
            <Routes>
              <Route path="/" element={<Home />} />
              <Route path="*" element={<Home />} />
            </Routes>
          </BrowserRouter>
        </div>
      </ThemeProvider>
    </HelmetProvider>
  );
}

export default App;
