import React, { useState, useEffect } from 'react';

const navItems = [
    { id: 'home',       label: 'Home' },
    { id: 'projects',   label: 'Projects' },
    { id: 'skills',     label: 'Skills' },
    { id: 'experience', label: 'Experience' },
    { id: 'certs',      label: 'Certifications' },
];

const Header = () => {
    const [scrolled, setScrolled] = useState(false);

    useEffect(() => {
        const handleScroll = () => setScrolled(window.scrollY > 20);
        window.addEventListener('scroll', handleScroll, { passive: true });
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    return (
        <header
            className={`fixed top-0 w-full z-50 transition-all duration-500 ${
                scrolled
                    ? 'bg-surface-container-low/80 backdrop-blur-2xl border-b border-white/[0.04] shadow-[0_1px_24px_rgba(0,0,0,0.4)]'
                    : 'bg-transparent'
            }`}
        >
            <div className="flex justify-between items-center max-w-7xl mx-auto px-6 md:px-8 py-4 md:py-5">
                {/* Logo */}
                <a href="#home" className="flex items-center gap-2.5 group">
                    <span className="material-symbols-outlined text-primary text-[26px] group-hover:scale-110 transition-transform">
                        memory
                    </span>
                    <span className="text-xl font-black tracking-tight text-on-surface">
                        <span className="text-on-surface-variant font-light">md</span>
                        <span className="text-gradient ml-1">ASIF</span>
                    </span>
                </a>

                {/* Desktop Nav */}
                <nav className="hidden md:flex items-center gap-1">
                    {navItems.map(({ id, label }) => (
                        <a
                            key={id}
                            href={`#${id}`}
                            className="px-4 py-2 rounded-xl text-sm font-medium text-on-surface-variant hover:text-on-surface hover:bg-surface-container-high transition-all duration-200"
                        >
                            {label}
                        </a>
                    ))}
                </nav>

                {/* Right Actions */}
                <div className="flex items-center gap-2">
                    <a
                        href="mailto:mdasifinit@gmail.com"
                        className="hidden md:inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-primary/10 text-primary text-sm font-semibold border border-primary/20 hover:bg-primary/20 transition-all"
                    >
                        <span className="material-symbols-outlined text-[16px]">mail</span>
                        Hire Me
                    </a>
                    <button className="p-2 rounded-xl hover:bg-surface-container-high transition-colors md:hidden">
                        <span className="material-symbols-outlined text-on-surface-variant text-[22px]">menu</span>
                    </button>
                </div>
            </div>
        </header>
    );
};

export default Header;
